class Solution {
    const unsigned long long BASE=911382323ULL;
    string text;
    int search(int length){
        unsigned long long power=1,hash=0;
        for(int i=0;i<length;++i){
            power*=BASE;
            hash=hash*BASE+(unsigned char)text[i];
        }
        unordered_map<unsigned long long,vector<int>> seen;
        seen[hash].push_back(0);
        for(int start=1;start+length<=(int)text.size();++start){
            hash=hash*BASE+(unsigned char)text[start+length-1]-power*(unsigned char)text[start-1];
            for(int previous:seen[hash])if(text.compare(previous,length,text,start,length)==0)return start;
            seen[hash].push_back(start);
        }
        return -1;
    }
    public:string longestDupSubstring(string s){
        text=s;
        int low=1,high=s.size()-1,bestStart=-1,bestLength=0;
        while(low<=high){
            int length=(low+high)/2,start=search(length);
            if(start>=0){
                bestStart=start;
                bestLength=length;
                low=length+1;
            }else high=length-1;
        }
        return bestStart<0?"":s.substr(bestStart,bestLength);
    }
};
